"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useControllableState } from "../lib/hooks";

interface RadioGroupContextValue {
  name: string;
  value: string | undefined;
  setValue: (value: string) => void;
  disabled?: boolean;
}

const RadioGroupContext = React.createContext<RadioGroupContextValue | null>(null);

export interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
  disabled?: boolean;
  orientation?: "vertical" | "horizontal";
}

/** RadioGroup — groep keuzerondjes met gedeelde naam en waarde. */
export const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(function RadioGroup(
  { value, defaultValue, onValueChange, name, disabled, orientation = "vertical", className, children, ...rest },
  ref
) {
  const autoName = React.useId();
  const [current, setCurrent] = useControllableState<string | undefined>({
    value,
    defaultValue,
    onChange: (next) => next !== undefined && onValueChange?.(next),
  });

  return (
    <RadioGroupContext.Provider
      value={{ name: name ?? `pxui-radio-${autoName}`, value: current, setValue: setCurrent, disabled }}
    >
      <div
        ref={ref}
        role="radiogroup"
        className={cn("pxui-radio-group", `pxui-radio-group-${orientation}`, className)}
        {...rest}
      >
        {children}
      </div>
    </RadioGroupContext.Provider>
  );
});

export interface RadioProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type"> {
  value: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** Rendert de optie als een klikbare kaart. */
  card?: boolean;
}

/** Radio — één optie binnen een RadioGroup. */
export const Radio = React.forwardRef<HTMLInputElement, RadioProps>(function Radio(
  { value, label, description, card, className, id, disabled, ...rest },
  ref
) {
  const group = React.useContext(RadioGroupContext);
  const autoId = React.useId();
  const inputId = id ?? `pxui-radio-item-${autoId}`;
  const isDisabled = disabled ?? group?.disabled;
  const checked = group ? group.value === value : undefined;

  return (
    <label
      htmlFor={inputId}
      className={cn(
        "pxui-radio-row",
        card && "pxui-radio-card",
        checked && "pxui-radio-checked",
        isDisabled && "pxui-radio-disabled",
        className
      )}
    >
      <span className="pxui-radio">
        <input
          ref={ref}
          id={inputId}
          type="radio"
          className="pxui-radio-input"
          name={group?.name}
          value={value}
          checked={checked}
          disabled={isDisabled}
          onChange={(event) => {
            group?.setValue(value);
            rest.onChange?.(event);
          }}
          {...rest}
        />
        <span className="pxui-radio-dot" aria-hidden="true" />
      </span>
      {(label || description) && (
        <span className="pxui-radio-text">
          {label && <span className="pxui-radio-label">{label}</span>}
          {description && <span className="pxui-radio-description">{description}</span>}
        </span>
      )}
    </label>
  );
});

/* ============================ RadioGroup ============================ */
.pxui-radio-group { display: flex; gap: 10px; }
.pxui-radio-group-vertical { flex-direction: column; }
.pxui-radio-group-horizontal { flex-direction: row; flex-wrap: wrap; gap: 18px; }

.pxui-radio { position: relative; display: inline-grid; place-items: center; flex: none; }
.pxui-radio-input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.pxui-radio-input:disabled { cursor: not-allowed; }

.pxui-radio-dot {
  width: 18px; height: 18px; border-radius: var(--r-full);
  background: var(--surface); border: 1.5px solid var(--border-strong);
  display: grid; place-items: center; pointer-events: none;
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}
.pxui-radio-dot::after {
  content: ""; width: 8px; height: 8px; border-radius: var(--r-full);
  background: var(--accent); transform: scale(0);
  transition: transform var(--dur-fast) var(--ease-pop);
}
.pxui-radio-input:hover:not(:disabled) + .pxui-radio-dot { border-color: var(--text-3); }
.pxui-radio-input:focus-visible + .pxui-radio-dot { border-color: var(--accent); box-shadow: var(--ring); }
.pxui-radio-input:checked + .pxui-radio-dot { border-color: var(--accent); }
.pxui-radio-input:checked + .pxui-radio-dot::after { transform: scale(1); }
.pxui-radio-input:disabled + .pxui-radio-dot { background: var(--surface-3); border-color: var(--border); }

.pxui-radio-row { display: flex; align-items: flex-start; gap: 10px; cursor: pointer; }
.pxui-radio-disabled { cursor: not-allowed; opacity: .6; }
.pxui-radio-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pxui-radio-label { font-size: 13.5px; font-weight: 550; color: var(--text); line-height: 1.35; }
.pxui-radio-description { font-size: var(--fs-sm); color: var(--text-3); line-height: 1.45; }

.pxui-radio-card {
  padding: 13px 15px; border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface); transition: border-color var(--dur), background var(--dur), box-shadow var(--dur);
}
.pxui-radio-card:hover:not(.pxui-radio-disabled) { border-color: var(--border-strong); }
.pxui-radio-card.pxui-radio-checked {
  border-color: var(--accent); background: var(--accent-tint); box-shadow: var(--sh-sm);
}
